# Let me manually trace through some possibilities
inputs = ['zy', 'zf', 'wczdb', 'uvb', 'ifiax']
outputs = ['zyf', 'zf', 'wczdb', 'givb', 'ifiax']

print("Checking pattern:")
for i, (inp, outp) in enumerate(zip(inputs, outputs)):
    print(f"{inp} -> {outp}")

# Try to identify what transformations occur
print("\nAnalyzing differences:")
for i, (inp, outp) in enumerate(zip(inputs, outputs)):
    print(f"'{inp}' vs '{outp}':")
    if len(inp) != len(outp):
        print(f"  Length changed: {len(inp)} -> {len(outp)}")
    else:
        print("  Same length")

    # Show differences character by character
    min_len = min(len(inp), len(outp))
    for j in range(min_len):
        if inp[j] != outp[j]:
            print(f"  Position {j}: '{inp[j]}' -> '{outp[j]}'")

    if len(inp) < len(outp):
        print(f"  Extra chars at end: '{outp[len(inp):]}'")
    elif len(inp) > len(outp):
        print(f"  Missing chars at end: '{inp[len(outp):]}'")

